<script>document.addEventListener('click',function(e){var b=e.target.closest('.mod-tab');if(!b)return;document.querySelectorAll('.mod-tab').forEach(x=>x.classList.remove('active'));document.querySelectorAll('.mod-pane').forEach(x=>x.classList.remove('active'));b.classList.add('active');var p=document.querySelector('[data-pane="'+b.dataset.tab+'"]');if(p)p.classList.add('active');});</script>